srcDoc.css:
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap");
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  min-height: 100%;
}

body {
  font-family: "DM Sans", sans-serif;
  background: transparent;
  color: #2F323B;
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  color: inherit;
}

[hidden] {
  display: none !important;
}

.constructor-app {
  --ink: #2F323B;
  --ink-soft: #414650;
  --blue: #2972A9;
  --blue-dark: #245F8B;
  --cyan: #2E9BCB;
  --cyan-soft: #DFF3FB;
  --light-blue: #A7CDDE;
  --paper: #FFFFFF;
  --surface: #F7FAFC;
  --surface-strong: #F1F6F9;
  --line: rgba(167, 205, 222, 0.58);
  --line-soft: rgba(167, 205, 222, 0.30);
  --text: #2F323B;
  --muted: #717983;
  --muted-soft: #9299A1;
  --success: #2C9A75;
  --warning: #C79443;
  --danger: #A95C5C;
  width: 100%;
  min-height: 100%;
  padding: 16px 10px 32px;
  background: radial-gradient(circle at 72% 8%, rgba(46, 155, 203, 0.065), transparent 26%), radial-gradient(circle at 8% 65%, rgba(167, 205, 222, 0.1), transparent 25%);
}

/* HEADER */
.constructor-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  margin-bottom: 18px;
  padding: 2px 4px 0;
}

.constructor-heading {
  min-width: 0;
  flex: 1;
}

.constructor-eyebrow {
  display: block;
  margin-bottom: 6px;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.constructor-heading h1 {
  margin-bottom: 7px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 29px;
  font-weight: 700;
  line-height: 1.15;
}

.constructor-heading p {
  max-width: 760px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}

.constructor-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-shrink: 0;
}

.new-query-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 142px;
  height: 42px;
  padding: 0 16px;
  border: 0;
  border-radius: 11px;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 8px 18px rgba(41, 114, 169, 0.18);
}

.new-query-button span {
  font-size: 16px;
}

/* SELECTOR */
.mode-selector {
  display: none;
  width: fit-content;
  margin: 0;
  padding: 4px;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.92);
}

.mode-selector.visible {
  display: flex;
}

.mode-option {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 132px;
  min-height: 42px;
  padding: 6px 10px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.mode-option.active {
  background: rgba(41, 114, 169, 0.09);
  color: var(--blue);
}

.mode-icon {
  width: 27px;
  height: 27px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 8px;
  background: rgba(167, 205, 222, 0.18);
  color: var(--blue);
  font-size: 12px;
  font-weight: 700;
}

.mode-copy {
  display: flex;
  flex-direction: column;
}

.mode-copy strong {
  font-size: 10.5px;
  font-weight: 700;
}

.mode-copy small {
  margin-top: 1px;
  color: var(--muted);
  font-size: 8px;
}

/* STEPPER */
.constructor-wizard {
  margin-bottom: 18px;
  padding: 14px 18px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.9);
}

.wizard-stepper {
  display: flex;
  align-items: center;
  width: 100%;
}

.wizard-step {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 128px;
  color: var(--muted);
}

.wizard-number {
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: #FFFFFF;
  font-size: 10px;
  font-weight: 800;
}

.wizard-step div {
  display: flex;
  flex-direction: column;
}

.wizard-step strong {
  font-size: 10.5px;
  font-weight: 700;
}

.wizard-step small {
  margin-top: 1px;
  color: var(--muted-soft);
  font-size: 8.5px;
}

.wizard-step.active .wizard-number {
  border-color: transparent;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
}

.wizard-step.active strong {
  color: var(--blue);
}

.wizard-step.completed .wizard-number {
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
}

.wizard-line {
  flex: 1;
  height: 1px;
  min-width: 20px;
  margin: 0 12px;
  background: var(--line);
}

.wizard-line.completed {
  background: rgba(41, 114, 169, 0.38);
}

/* MAIN */
.constructor-body {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(320px, 0.8fr);
  gap: 18px;
  align-items: start;
}

.constructor-main-view,
.constructor-library {
  min-width: 0;
}

/* HOME */
.constructor-home {
  min-height: 560px;
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.98), rgba(247, 250, 252, 0.96));
}

.home-intro {
  max-width: 690px;
  margin-bottom: 26px;
}

.home-kicker {
  display: block;
  margin-bottom: 7px;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.home-intro h2 {
  margin-bottom: 8px;
  color: var(--ink);
  font-family: "Playfair Display", serif;
  font-size: 26px;
}

.home-intro p {
  color: var(--muted);
  font-size: 12.5px;
  line-height: 1.65;
}

.creation-mode-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.creation-card {
  min-height: 330px;
  display: flex;
  flex-direction: column;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: #FFFFFF;
  text-align: left;
  cursor: pointer;
}

.creation-card-icon {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  border-radius: 12px;
  background: rgba(41, 114, 169, 0.09);
  color: var(--blue);
  font-size: 18px;
}

.creation-card-heading span {
  display: block;
  margin-bottom: 4px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.creation-card-heading h3 {
  margin-bottom: 10px;
  font-family: "Playfair Display", serif;
  font-size: 23px;
}

.creation-card > p {
  min-height: 50px;
  margin-bottom: 18px;
  color: var(--muted);
  font-size: 11.5px;
  line-height: 1.6;
}

.creation-benefits {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-bottom: 22px;
}

.creation-benefits span {
  font-size: 10.5px;
}

.creation-card-action {
  display: flex;
  justify-content: space-between;
  margin-top: auto;
  padding-top: 16px;
  border-top: 1px solid var(--line-soft);
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
}

/* WIZARD */
.wizard-view {
  min-height: 560px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.96);
}

.stage-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  margin-bottom: 20px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line-soft);
}

.stage-kicker {
  display: block;
  margin-bottom: 5px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.stage-header h2 {
  margin-bottom: 5px;
  font-family: "Playfair Display", serif;
  font-size: 22px;
}

.stage-header p {
  color: var(--muted);
  font-size: 11.5px;
}

.stage-badge {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
}

/* MANUAL PASO 1 */
.manual-rule-card {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 15px;
}

.manual-group-heading {
  grid-column: 1/-1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line-soft);
  background: rgba(167, 205, 222, 0.07);
}

.manual-group-heading span {
  display: block;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-group-heading strong {
  font-size: 12px;
}

.manual-logic-badge {
  width: 48px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 9px;
  font-weight: 800;
}

.manual-rule-row {
  min-width: 0;
  padding: 16px;
  border-right: 1px solid var(--line-soft);
}

.manual-rule-row:last-child {
  border-right: 0;
}

.manual-rule-copy {
  min-height: 76px;
}

.manual-rule-badge {
  display: inline-flex;
  margin-bottom: 7px;
  padding: 5px 8px;
  border-radius: 7px;
  font-size: 9px;
  font-weight: 800;
}

.manual-rule-badge.include {
  color: var(--blue);
  background: rgba(41, 114, 169, 0.09);
}

.manual-rule-badge.and {
  color: #2582A7;
  background: rgba(46, 155, 203, 0.1);
}

.manual-rule-badge.exclude {
  color: #8E4E4E;
  background: rgba(169, 92, 92, 0.09);
}

.manual-rule-copy strong {
  display: block;
  margin-bottom: 4px;
  font-size: 11.5px;
}

.manual-rule-copy p {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.manual-term-entry {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 7px;
}

.manual-term-input {
  width: 100%;
  min-width: 0;
  height: 38px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 9px;
  outline: none;
  background: #FBFDFE;
  font-size: 10px;
}

.manual-add-term {
  min-width: 70px;
  height: 38px;
  padding: 0 10px;
  border: 1px solid rgba(41, 114, 169, 0.18);
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.07);
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  cursor: pointer;
}

.manual-term-list {
  min-height: 42px;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 6px;
  margin-top: 7px;
  padding: 7px;
  border-radius: 9px;
  background: rgba(167, 205, 222, 0.07);
}

.manual-empty-terms {
  color: var(--muted-soft);
  font-size: 9px;
}

.manual-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 0 5px 0 9px;
  border-radius: 8px;
  color: var(--blue);
  background: rgba(41, 114, 169, 0.1);
  font-size: 10px;
  font-weight: 600;
}

.manual-chip-remove {
  width: 18px;
  height: 18px;
  border: 0;
  border-radius: 50%;
  cursor: pointer;
}

.manual-group-footer {
  padding-top: 10px;
}

.manual-add-group {
  width: 100%;
  height: 38px;
  border: 1px dashed rgba(41, 114, 169, 0.35);
  border-radius: 9px;
  background: transparent;
  color: var(--blue);
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.manual-stage-summary,
.manual-source-summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line-soft);
  border-radius: 10px;
  background: rgba(167, 205, 222, 0.06);
  font-size: 10px;
}

.manual-stage-summary strong,
.manual-source-summary strong {
  color: var(--blue);
}

/* MANUAL PASO 2 */
.manual-sources-section,
.manual-web-section {
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(180deg, #FFFFFF, #FBFDFE);
}

.manual-web-section {
  margin-top: 12px;
}

.manual-sources-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.manual-sources-heading span {
  display: block;
  margin-bottom: 2px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-sources-heading strong {
  display: block;
  font-size: 12px;
}

.manual-sources-heading small {
  color: var(--muted);
  font-size: 9px;
}

.manual-source-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.manual-web-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 10px;
}

.manual-source-card {
  position: relative;
  min-height: 94px;
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #FFFFFF;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.manual-source-card:hover {
  border-color: rgba(41, 114, 169, 0.36);
}

.manual-source-card.selected {
  border-color: rgba(41, 114, 169, 0.62);
  background: rgba(41, 114, 169, 0.055);
  box-shadow: 0 0 0 2px rgba(41, 114, 169, 0.05);
}

.manual-source-card.unavailable {
  opacity: 0.48;
  cursor: default;
}

.manual-source-icon {
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border-radius: 10px;
  background: rgba(46, 155, 203, 0.1);
  color: var(--blue);
  font-size: 14px;
  font-weight: 800;
}

.manual-source-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.manual-source-platform {
  margin-bottom: 2px;
  color: var(--blue);
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-source-content strong {
  overflow: hidden;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.manual-source-status,
.manual-source-description {
  margin-top: 4px;
  color: var(--muted);
  font-size: 9px;
}

.manual-status-dot {
  width: 6px;
  height: 6px;
  display: inline-block;
  margin-right: 4px;
  border-radius: 50%;
}

.manual-status-dot.active {
  background: var(--success);
}

.manual-status-dot.inactive {
  background: var(--muted-soft);
}

.manual-source-check {
  width: 23px;
  height: 23px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: #FFFFFF;
  color: #FFFFFF;
  font-size: 11px;
  font-weight: 800;
}

.manual-source-card.selected .manual-source-check {
  border-color: var(--blue);
  background: var(--blue);
}

.manual-source-switch {
  width: 40px;
  height: 23px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  padding: 2px;
  border-radius: 999px;
  background: rgba(113, 121, 131, 0.2);
  transition: background 0.18s ease;
}

.manual-source-switch span {
  width: 19px;
  height: 19px;
  display: block;
  border-radius: 50%;
  background: #FFFFFF;
  box-shadow: 0 2px 4px rgba(47, 50, 59, 0.12);
  transition: transform 0.18s ease;
}

.manual-source-switch.active {
  background: linear-gradient(135deg, var(--blue), var(--cyan));
}

.manual-source-switch.active span {
  transform: translateX(17px);
}

.manual-source-empty {
  grid-column: 1/-1;
  min-height: 100px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 20px;
  border: 1px dashed var(--line);
  border-radius: 12px;
  text-align: center;
}

.manual-source-empty strong {
  margin-bottom: 4px;
  font-size: 11px;
}

.manual-source-empty span {
  color: var(--muted);
  font-size: 9px;
}

.manual-source-summary > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.manual-source-summary-icon {
  width: 22px;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(44, 154, 117, 0.1);
  color: var(--success);
  font-weight: 800;
}

/* ACTIONS */
.stage-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--line-soft);
}

.stage-actions-right {
  display: flex;
  gap: 8px;
}

.stage-button {
  min-width: 120px;
  height: 40px;
  padding: 0 15px;
  border-radius: 10px;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
}

.stage-button.secondary {
  border: 1px solid var(--line);
  background: #FFFFFF;
  color: var(--blue);
}

.stage-button.primary {
  border: 0;
  background: linear-gradient(135deg, var(--blue), var(--cyan));
  color: #FFFFFF;
}

.stage-button:disabled {
  opacity: 0.45;
  cursor: default;
}

/* LIBRARY */
.constructor-library {
  position: sticky;
  top: 0;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.95);
}

.library-heading {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 15px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line-soft);
}

.library-kicker {
  display: block;
  margin-bottom: 4px;
  color: var(--blue);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.library-heading h2 {
  margin-bottom: 4px;
  font-family: "Playfair Display", serif;
  font-size: 19px;
}

.library-heading p {
  color: var(--muted);
  font-size: 10px;
}

.library-count {
  min-width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(41, 114, 169, 0.08);
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
}

.query-library-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 300px;
}

.saved-query-card {
  width: 100%;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #FFFFFF;
}

.saved-query-card-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 9px;
}

.saved-query-title {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.saved-query-title strong {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.saved-query-title span {
  color: var(--muted-soft);
  font-size: 8px;
}

.saved-query-status {
  height: 21px;
  padding: 4px 8px;
  border-radius: 999px;
  font-size: 8px;
}

.saved-query-status.active {
  color: #23775C;
  background: rgba(44, 154, 117, 0.1);
}

.saved-query-status.inactive {
  color: #777D85;
  background: rgba(115, 121, 130, 0.08);
}

.saved-query-formula {
  margin-bottom: 9px;
  padding: 8px;
  border-radius: 8px;
  background: rgba(167, 205, 222, 0.08);
  font-family: monospace;
  font-size: 9px;
}

.saved-query-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 5px;
  margin-bottom: 8px;
}

.saved-query-metrics span {
  padding: 6px 4px;
  border-radius: 7px;
  background: var(--surface);
  color: var(--muted);
  font-size: 7.5px;
  text-align: center;
}

.saved-query-metrics strong {
  display: block;
  color: var(--blue);
  font-size: 10px;
}

.saved-query-footer {
  padding-top: 7px;
  border-top: 1px solid var(--line-soft);
  color: var(--muted);
  font-size: 8.5px;
}

.library-empty {
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  border: 1px dashed var(--line);
  border-radius: 12px;
  text-align: center;
}

.empty-pulse {
  width: 38px;
  height: 38px;
  margin-bottom: 12px;
  border-radius: 11px;
  background: rgba(41, 114, 169, 0.1);
}

.library-empty strong {
  margin-bottom: 4px;
  font-size: 11px;
}

.library-empty span {
  color: var(--muted);
  font-size: 9px;
}

.library-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line-soft);
}

.library-pagination button {
  width: 31px;
  height: 31px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #FFFFFF;
  color: var(--blue);
}

.library-pagination button:disabled {
  opacity: 0.35;
}

.library-pagination span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
}

/* RESPONSIVE */
@media (max-width: 1180px) {
  .constructor-actions {
    flex-direction: column;
    align-items: stretch;
  }
}
@media (max-width: 1120px) {
  .constructor-body {
    grid-template-columns: 1fr;
  }
  .constructor-library {
    position: static;
  }
}
@media (max-width: 900px) {
  .manual-rule-card {
    grid-template-columns: 1fr;
  }
  .manual-rule-row {
    border-right: 0;
    border-bottom: 1px solid var(--line-soft);
  }
  .manual-source-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 820px) {
  .constructor-top {
    flex-direction: column;
  }
  .constructor-actions {
    width: 100%;
  }
  .mode-selector {
    width: 100%;
  }
  .mode-option {
    flex: 1;
  }
  .creation-mode-grid {
    grid-template-columns: 1fr;
  }
  .wizard-stepper {
    overflow-x: auto;
  }
}
@media (max-width: 560px) {
  .constructor-app {
    padding: 10px 5px 22px;
  }
  .constructor-heading h1 {
    font-size: 25px;
  }
  .mode-selector {
    flex-direction: column;
  }
  .manual-source-grid {
    grid-template-columns: 1fr;
  }
  .manual-term-entry {
    grid-template-columns: 1fr;
  }
  .stage-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .stage-button {
    width: 100%;
  }
}

