appsmith.onReady(function () {
  var currentPage = 1;
  var currentMode = 'home';
  var currentStep = 0;
  var groups = [];
  var selectedTargetIds = [];
  var useWeb = false;
  var lastQueriesValue = null;
  var lastTargetsValue = null;
  var lastModeValue = null;
  var lastStepValue = null;
  var lastGroupsValue = null;
  var lastTargetIdsValue = null;
  var lastUseWebValue = null;
  var lastAiResponseValue = null;
  var aiRequestPending = false;
  var aiFeedbackMessage = '';
  var aiWarnings = [];
  var aiGenerateArmed = false;
  var aiGenerateInstruction = '';
  function getModel() {
    return appsmith.model || {};
  }
  function escapeHtml(value) {
    var div = document.createElement('div');
    div.textContent = value == null ? '' : String(value);
    return div.innerHTML;
  }
  function asArray(value) {
    if (Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return [];
    }
    var text = value.trim();
    try {
      var parsed = JSON.parse(text);
      return Array.isArray(parsed) ? parsed : [];
    } catch (directError) {
      try {
        var decoded = decodeURIComponent(text);
        var decodedParsed = JSON.parse(decoded);
        return Array.isArray(decodedParsed) ? decodedParsed : [];
      } catch (decodedError) {
        return [];
      }
    }
  }
  function asObject(value) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      return value;
    }
    if (typeof value !== 'string' || value.trim() === '') {
      return {};
    }
    var text = value.trim();
    try {
      var parsed = JSON.parse(text);
      return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch (directError) {
      try {
        var decoded = decodeURIComponent(text);
        var decodedParsed = JSON.parse(decoded);
        return decodedParsed && typeof decodedParsed === 'object' && !Array.isArray(decodedParsed) ? decodedParsed : {};
      } catch (decodedError) {
        return {};
      }
    }
  }
  function normalizeTerms(value) {
    if (!Array.isArray(value)) {
      return [];
    }
    return value.map(function (term) {
      return String(term == null ? '' : term).trim();
    }).filter(function (term) {
      return term !== '';
    });
  }
  function createEmptyGroup(groupNo) {
    return {
      group_no: groupNo,
      include: [],
      and: [],
      and_not: []
    };
  }
  function normalizeGroup(group, index) {
    return {
      group_no: index + 1,
      include: normalizeTerms(group && group.include),
      and: normalizeTerms(group && group.and),
      and_not: normalizeTerms(group && group.and_not)
    };
  }
  function loadGroupsFromModel() {
    var raw = getModel().query_groups_json;
    var parsed = [];
    if (Array.isArray(raw)) {
      parsed = raw;
    } else if (typeof raw === 'string' && raw.trim() !== '') {
      try {
        parsed = JSON.parse(raw);
      } catch (error) {
        parsed = [];
      }
    }
    if (!Array.isArray(parsed) || parsed.length === 0) {
      groups = [createEmptyGroup(1)];
      return;
    }
    groups = parsed.map(normalizeGroup);
  }
  function loadSourcesFromModel() {
    selectedTargetIds = asArray(getModel().query_target_ids_json).map(function (id) {
      return String(id);
    });
    useWeb = getModel().query_use_web === true || String(getModel().query_use_web).toLowerCase() === 'true';
  }
  function formatDate(value) {
    if (!value) {
      return '';
    }
    try {
      return new Intl.DateTimeFormat('es', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      }).format(new Date(value));
    } catch (error) {
      return '';
    }
  }
  function getQueries() {
    return asArray(getModel().queries);
  }
  function getTargets() {
    return asArray(getModel().targets);
  }
  function getMode() {
    if (currentMode !== 'manual' && currentMode !== 'ai') {
      return 'home';
    }
    return currentMode;
  }
  function getStep() {
    if (isNaN(currentStep) || currentStep < 0) {
      return 0;
    }
    if (currentStep > 4) {
      return 4;
    }
    return currentStep;
  }
  function getPageSize() {
    var value = parseInt(getModel().queries_page_size || 3, 10);
    if (isNaN(value) || value < 1) {
      return 3;
    }
    return value;
  }
  function getMaxGroups() {
    var value = parseInt(getModel().query_max_groups || 3, 10);
    if (isNaN(value) || value < 1) {
      return 3;
    }
    return value;
  }
  function getTotalPages() {
    var queries = getQueries();
    var pageSize = getPageSize();
    return Math.max(1, Math.ceil(queries.length / pageSize));
  }
  function clampPage() {
    var totalPages = getTotalPages();
    if (currentPage > totalPages) {
      currentPage = totalPages;
    }
    if (currentPage < 1) {
      currentPage = 1;
    }
  }
  function quoteTerm(term) {
    return '"' + String(term).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
  }
  function buildGroupFormula(group) {
    if (!group || group.include.length === 0) {
      return '';
    }
    var includeFormula = group.include.map(quoteTerm).join(' OR ');
    if (group.include.length > 1) {
      includeFormula = '(' + includeFormula + ')';
    }
    var parts = [includeFormula];
    group.and.forEach(function (term) {
      parts.push('AND ' + quoteTerm(term));
    });
    group.and_not.forEach(function (term) {
      parts.push('AND NOT ' + quoteTerm(term));
    });
    return parts.join(' ');
  }
  function buildFormula() {
    var formulas = groups.map(buildGroupFormula).filter(function (formula) {
      return formula !== '';
    });
    if (formulas.length === 0) {
      return '';
    }
    if (formulas.length === 1) {
      return formulas[0];
    }
    return formulas.map(function (formula) {
      return '(' + formula + ')';
    }).join(' OR ');
  }
  function getTotalTerms() {
    return groups.reduce(function (total, group) {
      return total + group.include.length + group.and.length + group.and_not.length;
    }, 0);
  }
  function hasValidManualRules() {
    if (groups.length === 0) {
      return false;
    }
    return groups.every(function (group) {
      return group.include.length > 0;
    });
  }
  function getSelectableTargets() {
    return getTargets().filter(function (target) {
      return target && target.id && target.status === 'active';
    });
  }
  function getValidSelectedTargetIds() {
    var availableIds = getSelectableTargets().map(function (target) {
      return String(target.id);
    });
    return selectedTargetIds.filter(function (id) {
      return availableIds.indexOf(String(id)) !== -1;
    });
  }
  function getSelectedTargets() {
    var validIds = getValidSelectedTargetIds();
    return getTargets().filter(function (target) {
      return target && validIds.indexOf(String(target.id)) !== -1;
    });
  }
  function hasValidSources() {
    return getValidSelectedTargetIds().length > 0 || useWeb;
  }
  function hasValidPreview() {
    return hasValidManualRules() && buildFormula() !== '' && hasValidSources();
  }
  function getQueryName() {
    return String(getModel().query_name || '').trim();
  }
  function getQueryStatus() {
    var status = String(getModel().query_status || 'active').trim().toLowerCase();
    return status === 'inactive' ? 'inactive' : 'active';
  }
  function getAiInstruction() {
    return String(getModel().ai_instruction || '').trim();
  }
  function getAiExplanation() {
    return String(getModel().ai_explanation || '').trim();
  }
  function hasValidSaveForm() {
    return getQueryName() !== '' && hasValidPreview();
  }
  async function syncQueryPayload() {
    var groupsJson = JSON.stringify(groups);
    var formula = buildFormula();
    lastGroupsValue = groupsJson;
    try {
      await appsmith.updateModel({
        query_groups_json: groupsJson,
        query_formula: formula
      });
    } catch (error) {
      console.error('No fue posible sincronizar las reglas:', error);
    }
  }
  async function syncSourcePayload() {
    var idsJson = JSON.stringify(selectedTargetIds);
    lastTargetIdsValue = idsJson;
    lastUseWebValue = String(useWeb);
    try {
      await appsmith.updateModel({
        query_target_ids_json: idsJson,
        query_use_web: useWeb
      });
    } catch (error) {
      console.error('No fue posible sincronizar las fuentes:', error);
    }
  }
  function renderQueryCard(query) {
    var statusLabel = query.status === 'active' ? 'Activa' : 'Inactiva';
    var updatedDate = formatDate(query.updated_at || query.created_at);
    return '<article class="saved-query-card">' + '<div class="saved-query-card-head">' + '<div class="saved-query-title">' + '<strong>' + escapeHtml(query.name || '') + '</strong>' + '<span>' + escapeHtml(updatedDate) + '</span>' + '</div>' + '<span class="saved-query-status ' + (query.status === 'active' ? 'active' : 'inactive') + '">' + escapeHtml(statusLabel) + '</span>' + '</div>' + '<div class="saved-query-formula">' + escapeHtml(query.formula_text || '') + '</div>' + '<div class="saved-query-metrics">' + '<span>' + '<strong>' + escapeHtml(query.groups_count || 0) + '</strong>' + 'grupo(s)' + '</span>' + '<span>' + '<strong>' + escapeHtml(query.terms_count || 0) + '</strong>' + 'término(s)' + '</span>' + '<span>' + '<strong>' + escapeHtml(query.targets_count || 0) + '</strong>' + 'objetivo(s)' + '</span>' + '</div>' + '<div class="saved-query-footer">' + '<span>' + 'Web: ' + (query.use_web ? 'Sí' : 'No') + '</span>' + '</div>' + '</article>';
  }
  function renderLibrary() {
    var queries = getQueries();
    var countElement = document.getElementById('savedQueriesCount');
    var listElement = document.getElementById('savedQueriesList');
    var paginationElement = document.getElementById('savedQueriesPagination');
    if (!countElement || !listElement || !paginationElement) {
      return;
    }
    countElement.textContent = String(queries.length);
    clampPage();
    if (queries.length === 0) {
      listElement.innerHTML = '<div class="library-empty">' + '<div class="empty-pulse"></div>' + '<strong>' + 'Sin consultas guardadas' + '</strong>' + '<span>' + 'Las consultas creadas aparecerán aquí.' + '</span>' + '</div>';
      paginationElement.innerHTML = '<button type="button" disabled>' + '←' + '</button>' + '<span>' + 'Página 1 de 1' + '</span>' + '<button type="button" disabled>' + '→' + '</button>';
      return;
    }
    var pageSize = getPageSize();
    var startIndex = (currentPage - 1) * pageSize;
    var visibleQueries = queries.slice(startIndex, startIndex + pageSize);
    listElement.innerHTML = visibleQueries.map(renderQueryCard).join('');
    var totalPages = getTotalPages();
    paginationElement.innerHTML = '<button' + ' type="button"' + ' data-action="prev-page"' + (currentPage <= 1 ? ' disabled' : '') + '>' + '←' + '</button>' + '<span>' + 'Página ' + escapeHtml(currentPage) + ' de ' + escapeHtml(totalPages) + '</span>' + '<button' + ' type="button"' + ' data-action="next-page"' + (currentPage >= totalPages ? ' disabled' : '') + '>' + '→' + '</button>';
  }
  function getViewElement(mode, step) {
    if (mode === 'manual') {
      return document.getElementById('manualStep' + String(step));
    }
    if (mode === 'ai') {
      return document.getElementById('aiStep' + String(step));
    }
    return null;
  }
  function hideAllViews() {
    var home = document.getElementById('constructorHome');
    if (home) {
      home.hidden = true;
    }
    var views = document.querySelectorAll('.wizard-view');
    views.forEach(function (view) {
      view.hidden = true;
    });
  }
  function renderModeSelector(mode) {
    var selector = document.getElementById('constructorModeSelector');
    if (!selector) {
      return;
    }
    if (mode === 'home') {
      selector.classList.remove('visible');
      return;
    }
    selector.classList.add('visible');
    var buttons = selector.querySelectorAll('[data-mode]');
    buttons.forEach(function (button) {
      var buttonMode = button.getAttribute('data-mode');
      button.classList.toggle('active', buttonMode === mode);
    });
  }
  function setWizardLabels(mode) {
    var step1Title = document.getElementById('wizardStep1Title');
    var step1Subtitle = document.getElementById('wizardStep1Subtitle');
    var step2Title = document.getElementById('wizardStep2Title');
    var step2Subtitle = document.getElementById('wizardStep2Subtitle');
    if (!step1Title || !step1Subtitle || !step2Title || !step2Subtitle) {
      return;
    }
    if (mode === 'ai') {
      step1Title.textContent = 'Describir';
      step1Subtitle.textContent = 'Explica qué monitorear';
      step2Title.textContent = 'Revisar propuesta';
      step2Subtitle.textContent = 'Ajusta la propuesta';
      return;
    }
    step1Title.textContent = 'Construir';
    step1Subtitle.textContent = 'Define las reglas';
    step2Title.textContent = 'Fuentes';
    step2Subtitle.textContent = 'Selecciona dónde escuchar';
  }
  function renderStepper(mode, step) {
    var wizard = document.getElementById('constructorWizard');
    if (!wizard) {
      return;
    }
    if (mode === 'home') {
      wizard.hidden = true;
      return;
    }
    wizard.hidden = false;
    setWizardLabels(mode);
    var steps = wizard.querySelectorAll('.wizard-step');
    steps.forEach(function (stepElement) {
      var stepNumber = parseInt(stepElement.getAttribute('data-step'), 10);
      stepElement.classList.toggle('active', stepNumber === step);
      stepElement.classList.toggle('completed', stepNumber < step);
      var numberElement = stepElement.querySelector('.wizard-number');
      if (numberElement) {
        numberElement.textContent = stepNumber < step ? '✓' : String(stepNumber);
      }
    });
    var lines = wizard.querySelectorAll('.wizard-line');
    lines.forEach(function (line, index) {
      line.classList.toggle('completed', index + 1 < step);
    });
  }
  function getOperatorTerms(group, operator) {
    if (!group) {
      return [];
    }
    if (operator === 'include') {
      return group.include;
    }
    if (operator === 'and') {
      return group.and;
    }
    if (operator === 'and_not') {
      return group.and_not;
    }
    return [];
  }
  function getOperatorChipClass(operator) {
    if (operator === 'and') {
      return 'and';
    }
    if (operator === 'and_not') {
      return 'exclude';
    }
    return '';
  }
  function getEmptyTermsText(operator) {
    if (operator === 'include') {
      return 'Agrega al menos un término para este grupo.';
    }
    if (operator === 'and') {
      return 'Sin condiciones obligatorias.';
    }
    return 'Sin exclusiones.';
  }
  function renderTerms(group, operator) {
    var terms = getOperatorTerms(group, operator);
    if (terms.length === 0) {
      return '<span class="manual-empty-terms">' + escapeHtml(getEmptyTermsText(operator)) + '</span>';
    }
    var chipClass = getOperatorChipClass(operator);
    return terms.map(function (term, index) {
      return '<span class="manual-chip' + (chipClass ? ' ' + chipClass : '') + '">' + '<span>' + escapeHtml(term) + '</span>' + '<button' + ' type="button"' + ' class="manual-chip-remove"' + ' data-remove-term="' + escapeHtml(operator) + '"' + ' data-group-no="' + escapeHtml(group.group_no) + '"' + ' data-term-index="' + escapeHtml(index) + '"' + ' aria-label="Eliminar término"' + '>' + '×' + '</button>' + '</span>';
    }).join('');
  }
  function renderRuleRow(group, operator) {
    var badge = '';
    var badgeClass = '';
    var title = '';
    var description = '';
    var placeholder = '';
    if (operator === 'include') {
      badge = 'INCLUIR';
      badgeClass = 'include';
      title = 'Palabras o frases';
      description = 'Basta con que aparezca uno de estos términos.';
      placeholder = 'Añadir palabra o frase';
    }
    if (operator === 'and') {
      badge = 'AND';
      badgeClass = 'and';
      title = 'También debe contener';
      description = 'Condiciones que deben cumplirse simultáneamente.';
      placeholder = 'Añadir condición obligatoria';
    }
    if (operator === 'and_not') {
      badge = 'AND NOT';
      badgeClass = 'exclude';
      title = 'Excluir';
      description = 'Descarta resultados que contengan estos términos.';
      placeholder = 'Añadir término a excluir';
    }
    return '<div class="manual-rule-row">' + '<div class="manual-rule-copy">' + '<span class="manual-rule-badge ' + badgeClass + '">' + escapeHtml(badge) + '</span>' + '<strong>' + escapeHtml(title) + '</strong>' + '<p>' + escapeHtml(description) + '</p>' + '</div>' + '<div class="manual-rule-editor">' + '<div class="manual-term-entry">' + '<input' + ' type="text"' + ' class="manual-term-input"' + ' data-term-input="' + escapeHtml(operator) + '"' + ' data-group-no="' + escapeHtml(group.group_no) + '"' + ' maxlength="500"' + ' placeholder="' + escapeHtml(placeholder) + '"' + ' autocomplete="off"' + '>' + '<button' + ' type="button"' + ' class="manual-add-term"' + ' data-add-term="' + escapeHtml(operator) + '"' + ' data-group-no="' + escapeHtml(group.group_no) + '"' + '>' + 'Agregar' + '</button>' + '</div>' + '<div class="manual-term-list">' + renderTerms(group, operator) + '</div>' + '</div>' + '</div>';
  }
  function renderManualGroup(group) {
    return '<div' + ' class="manual-rule-card"' + ' data-manual-group="' + escapeHtml(group.group_no) + '"' + '>' + '<div class="manual-group-heading">' + '<div>' + '<span>' + 'Grupo ' + escapeHtml(group.group_no) + '</span>' + '<strong>' + (group.group_no === 1 ? 'Regla principal' : 'Grupo alternativo') + '</strong>' + '</div>' + '<span class="manual-logic-badge">' + (group.group_no === 1 ? 'BASE' : 'OR') + '</span>' + '</div>' + renderRuleRow(group, 'include') + renderRuleRow(group, 'and') + renderRuleRow(group, 'and_not') + '</div>';
  }
  function renderManualStep1(element) {
    if (!element) {
      return;
    }
    var maxGroups = getMaxGroups();
    var formula = buildFormula();
    var totalTerms = getTotalTerms();
    var valid = hasValidManualRules();
    element.innerHTML = '<div class="stage-header">' + '<div>' + '<span class="stage-kicker">' + 'Modo manual' + '</span>' + '<h2>' + 'Define las reglas de escucha' + '</h2>' + '<p>' + 'Agrega palabras o frases, condiciones obligatorias y exclusiones.' + '</p>' + '</div>' + '<span class="stage-badge">' + 'Paso 1 de 4' + '</span>' + '</div>' + '<div id="manualGroupsContainer">' + groups.map(renderManualGroup).join('') + '</div>' + '<div class="manual-group-footer">' + '<button' + ' type="button"' + ' class="manual-add-group"' + ' data-add-group="true"' + (groups.length >= maxGroups ? ' disabled' : '') + '>' + '<span>+</span>' + (groups.length >= maxGroups ? 'Máximo de grupos alcanzado' : 'Agregar otro grupo') + '</button>' + '</div>' + '<div class="manual-stage-summary">' + '<span>' + (valid ? 'Reglas listas para continuar.' : 'Cada grupo necesita al menos un término en INCLUIR.') + '</span>' + '<strong>' + escapeHtml(totalTerms) + ' término(s)' + (formula ? ' · Fórmula generada' : '') + '</strong>' + '</div>' + '<div class="stage-actions">' + '<button' + ' type="button"' + ' class="stage-button secondary"' + ' data-nav-home="true"' + '>' + '← Volver' + '</button>' + '<div class="stage-actions-right">' + '<button' + ' type="button"' + ' class="stage-button primary"' + ' data-next-step="2"' + (valid ? '' : ' disabled') + '>' + 'Continuar a fuentes →' + '</button>' + '</div>' + '</div>';
  }
  function getTargetDisplayName(target) {
    return target.handle || target.external_profile_id || 'Objetivo social';
  }
  function formatPlatformLabel(value) {
    var text = String(value || '').trim().replace(/[_-]+/g, ' ');
    if (!text) {
      return 'Red social';
    }
