    var valid = normalizedName !== '' && hasValidPreview();
    var summaryIcon = document.getElementById('manualSaveSummaryIcon');
    var summaryText = document.getElementById('manualSaveSummaryText');
    var summaryState = document.getElementById('manualSaveSummaryState');
    var saveButton = document.getElementById('manualSaveQueryButton');
    if (summaryIcon) {
      summaryIcon.textContent = valid ? '✓' : '!';
    }
    if (summaryText) {
      summaryText.textContent = (normalizedName ? 'Nombre definido' : 'Falta asignar un nombre') + ' · Web: ' + (useWeb ? 'Sí' : 'No');
    }
    if (summaryState) {
      summaryState.textContent = valid ? 'Lista para guardarse' : 'Completa los datos requeridos';
    }
    if (saveButton) {
      saveButton.disabled = !valid;
    }
  }
  async function syncSaveForm() {
    var nameInput = document.getElementById('manualQueryName');
    var statusInput = document.getElementById('manualQueryStatus');
    var name = nameInput ? String(nameInput.value || '').trim() : getQueryName();
    var status = statusInput ? String(statusInput.value || 'active') : getQueryStatus();
    await appsmith.updateModel({
      query_name: name,
      query_status: status
    });
    updateSaveSummary(name);
  }
  async function saveManualQuery() {
    var nameInput = document.getElementById('manualQueryName');
    var statusInput = document.getElementById('manualQueryStatus');
    var name = nameInput ? String(nameInput.value || '').trim() : '';
    var status = statusInput ? String(statusInput.value || 'active') : 'active';
    if (name === '' || !hasValidPreview()) {
      return;
    }
    await appsmith.updateModel({
      query_name: name,
      query_status: status,
      query_formula: buildFormula(),
      query_groups_json: JSON.stringify(groups),
      query_target_ids_json: JSON.stringify(selectedTargetIds),
      query_use_web: useWeb
    });
    appsmith.triggerEvent('onSaveQuery');
  }
  async function resetConstructor() {
    currentMode = 'home';
    currentStep = 0;
    aiRequestPending = false;
    aiGenerateArmed = false;
    aiGenerateInstruction = '';
    aiFeedbackMessage = '';
    aiWarnings = [];
    groups = [createEmptyGroup(1)];
    selectedTargetIds = [];
    useWeb = false;
    var groupsJson = JSON.stringify(groups);
    var idsJson = JSON.stringify(selectedTargetIds);
    lastGroupsValue = groupsJson;
    lastTargetIdsValue = idsJson;
    lastUseWebValue = 'false';
    await appsmith.updateModel({
      constructor_mode: 'home',
      constructor_step: 0,
      query_name: '',
      query_status: 'active',
      query_formula: '',
      query_use_web: false,
      query_groups_json: groupsJson,
      query_target_ids_json: idsJson,
      ai_instruction: '',
      ai_proposal_json: '{}',
      ai_explanation: '',
      ai_generated: false
    });
    renderCurrentView();
  }
  document.addEventListener('input', function (event) {
    if (event.target && event.target.id === 'manualQueryName') {
      syncSaveForm();
    }
    if (event.target && event.target.id === 'aiInstructionInput') {
      var aiButton = document.getElementById('aiGenerateButton');
      var aiText = String(event.target.value || '').trim();
      if (aiButton) {
        aiButton.disabled = aiRequestPending || aiText.length < 20 || aiText.length > 1500;
      }
    }
  });
  document.addEventListener('change', function (event) {
    if (event.target && event.target.id === 'manualQueryStatus') {
      syncSaveForm();
    }
  });
  document.addEventListener('keydown', function (event) {
    if (event.key !== 'Enter') {
      return;
    }
    var input = event.target.closest('.manual-term-input[data-term-input]');
    if (!input) {
      return;
    }
    event.preventDefault();
    var groupNo = input.getAttribute('data-group-no');
    var operator = input.getAttribute('data-term-input');
    var button = document.querySelector('.manual-add-term' + '[data-group-no="' + groupNo + '"]' + '[data-add-term="' + operator + '"]');
    if (button) {
      addTerm(button);
    }
  });
  document.addEventListener('click', function (event) {
    var generateAiButton = event.target.closest('[data-generate-ai]');
    if (generateAiButton) {
      generateAiProposal();
      return;
    }
    var saveButton = event.target.closest('[data-save-query]');
    if (saveButton) {
      saveManualQuery();
      return;
    }
    var sourceTarget = event.target.closest('[data-source-target-id]');
    if (sourceTarget) {
      toggleTarget(sourceTarget.getAttribute('data-source-target-id'));
      return;
    }
    var webSource = event.target.closest('[data-toggle-web]');
    if (webSource) {
      toggleWeb();
      return;
    }
    var addTermButton = event.target.closest('[data-add-term]');
    if (addTermButton) {
      addTerm(addTermButton);
      return;
    }
    var removeTermButton = event.target.closest('[data-remove-term]');
    if (removeTermButton) {
      removeTerm(removeTermButton);
      return;
    }
    var addGroupButton = event.target.closest('[data-add-group]');
    if (addGroupButton) {
      addGroup();
      return;
    }
    var nextStepButton = event.target.closest('[data-next-step]');
    if (nextStepButton) {
      setStep(nextStepButton.getAttribute('data-next-step'));
      return;
    }
    var prevStepButton = event.target.closest('[data-prev-step]');
    if (prevStepButton) {
      setStep(prevStepButton.getAttribute('data-prev-step'));
      return;
    }
    var homeButton = event.target.closest('[data-nav-home]');
    if (homeButton) {
      resetConstructor();
      return;
    }
    var startModeButton = event.target.closest('[data-start-mode]');
    if (startModeButton) {
      setMode(startModeButton.getAttribute('data-start-mode'));
      return;
    }
    var modeButton = event.target.closest('[data-mode]');
    if (modeButton) {
      setMode(modeButton.getAttribute('data-mode'));
      return;
    }
    var newQueryButton = event.target.closest('#newQueryButton');
    if (newQueryButton) {
      resetConstructor();
      return;
    }
    var paginationButton = event.target.closest('[data-action]');
    if (!paginationButton) {
      return;
    }
    var action = paginationButton.getAttribute('data-action');
    if (action === 'prev-page') {
      if (currentPage > 1) {
        currentPage -= 1;
        renderLibrary();
      }
      return;
    }
    if (action === 'next-page') {
      var totalPages = getTotalPages();
      if (currentPage < totalPages) {
        currentPage += 1;
        renderLibrary();
      }
    }
  });
  var initialMode = String(getModel().constructor_mode || 'home').trim().toLowerCase();
  currentMode = initialMode === 'manual' || initialMode === 'ai' ? initialMode : 'home';
  var initialStep = parseInt(getModel().constructor_step || 0, 10);
  currentStep = !isNaN(initialStep) && initialStep >= 0 && initialStep <= 4 ? initialStep : 0;
  loadGroupsFromModel();
  loadSourcesFromModel();
  renderLibrary();
  renderCurrentView();
  lastQueriesValue = String(getModel().queries || '');
  lastTargetsValue = String(getModel().targets || '');
  lastModeValue = String(getModel().constructor_mode || 'home');
  lastStepValue = String(getModel().constructor_step || 0);
  lastGroupsValue = String(getModel().query_groups_json || '[]');
  lastTargetIdsValue = String(getModel().query_target_ids_json || '[]');
  lastUseWebValue = String(getModel().query_use_web || false);
  lastAiResponseValue = String(getModel().ai_response || '');
  if (typeof appsmith.onModelChange === 'function') {
    appsmith.onModelChange(function (newModel) {
      var model = newModel || getModel();
      var queriesValue = String(model.queries || '');
      var targetsValue = String(model.targets || '');
      var modeValue = String(model.constructor_mode || 'home');
      var stepValue = String(model.constructor_step || 0);
      var groupsValue = String(model.query_groups_json || '[]');
      var targetIdsValue = String(model.query_target_ids_json || '[]');
      var useWebValue = String(model.query_use_web || false);
      var aiResponseValue = String(model.ai_response || '');
      var aiInstructionValue = String(model.ai_instruction || '').trim();
      if (aiGenerateArmed && aiRequestPending && getMode() === 'ai' && aiInstructionValue === aiGenerateInstruction) {
        aiGenerateArmed = false;
        appsmith.triggerEvent('onGenerateAI');
      }
      if (queriesValue !== lastQueriesValue) {
        lastQueriesValue = queriesValue;
        currentPage = 1;
        renderLibrary();
      }
      if (targetsValue !== lastTargetsValue) {
        lastTargetsValue = targetsValue;
        if (modeValue === 'manual' && (stepValue === '2' || stepValue === '3' || stepValue === '4')) {
          renderCurrentView();
        }
      }
      if (groupsValue !== lastGroupsValue) {
        lastGroupsValue = groupsValue;
        loadGroupsFromModel();
        if (modeValue === 'manual' && (stepValue === '1' || stepValue === '3' || stepValue === '4')) {
          renderCurrentView();
        }
      }
      if (targetIdsValue !== lastTargetIdsValue || useWebValue !== lastUseWebValue) {
        lastTargetIdsValue = targetIdsValue;
        lastUseWebValue = useWebValue;
        loadSourcesFromModel();
        if (modeValue === 'manual' && (stepValue === '2' || stepValue === '3' || stepValue === '4')) {
          renderCurrentView();
        }
      }
      if (aiResponseValue !== lastAiResponseValue) {
        lastAiResponseValue = aiResponseValue;
        if (getMode() === 'ai') {
          var aiResponse = asObject(model.ai_response);
          if (Object.keys(aiResponse).length > 0 && (aiResponse.ok === true || aiResponse.needs_clarification === true)) {
            applyAiResponse(aiResponse);
          }
        }
      }
      if (modeValue !== lastModeValue || stepValue !== lastStepValue) {
        lastModeValue = modeValue;
        lastStepValue = stepValue;
        renderCurrentView();
      }
    });
  }
});

