  padding: 4px 8px;

  border-radius: 999px;

  font-size: 8px;
}

.saved-query-status.active {
  color: #23775C;

  background:
    rgba(44, 154, 117, 0.10);
}

.saved-query-status.inactive {
  color: #777D85;

  background:
    rgba(115, 121, 130, 0.08);
}

.saved-query-formula {
  margin-bottom: 9px;

  padding: 8px;

  border-radius: 8px;

  background:
    rgba(167, 205, 222, 0.08);

  font-family: monospace;

  font-size: 9px;
}

.saved-query-metrics {
  display: grid;

  grid-template-columns:
    repeat(3, 1fr);

  gap: 5px;

  margin-bottom: 8px;
}

.saved-query-metrics span {
  padding: 6px 4px;

  border-radius: 7px;

  background: var(--surface);

  color: var(--muted);

  font-size: 7.5px;

  text-align: center;
}

.saved-query-metrics strong {
  display: block;

  color: var(--blue);

  font-size: 10px;
}

.saved-query-footer {
  padding-top: 7px;

  border-top:
    1px solid var(--line-soft);

  color: var(--muted);

  font-size: 8.5px;
}

.library-empty {
  min-height: 280px;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

  border:
    1px dashed var(--line);

  border-radius: 12px;

  text-align: center;
}

.empty-pulse {
  width: 38px;
  height: 38px;

  margin-bottom: 12px;

  border-radius: 11px;

  background:
    rgba(41, 114, 169, 0.10);
}

.library-empty strong {
  margin-bottom: 4px;

  font-size: 11px;
}

.library-empty span {
  color: var(--muted);

  font-size: 9px;
}

.library-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 8px;

  margin-top: 12px;

  padding-top: 12px;

  border-top:
    1px solid var(--line-soft);
}

.library-pagination button {
  width: 31px;
  height: 31px;

  border:
    1px solid var(--line);

  border-radius: 8px;

  background: #FFFFFF;

  color: var(--blue);
}

.library-pagination button:disabled {
  opacity: 0.35;
}

.library-pagination span {
  color: var(--muted);

  font-size: 9px;
  font-weight: 600;
}

/* RESPONSIVE */

@media (max-width: 1180px) {
  .constructor-actions {
    flex-direction: column;
    align-items: stretch;
  }
}

@media (max-width: 1120px) {
  .constructor-body {
    grid-template-columns: 1fr;
  }

  .constructor-library {
    position: static;
  }
}

@media (max-width: 900px) {
  .manual-rule-card {
    grid-template-columns: 1fr;
  }

  .manual-rule-row {
    border-right: 0;

    border-bottom:
      1px solid var(--line-soft);
  }

  .manual-source-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 820px) {
  .constructor-top {
    flex-direction: column;
  }

  .constructor-actions {
    width: 100%;
  }

  .mode-selector {
    width: 100%;
  }

  .mode-option {
    flex: 1;
  }

  .creation-mode-grid {
    grid-template-columns: 1fr;
  }

  .wizard-stepper {
    overflow-x: auto;
  }
}

@media (max-width: 560px) {
  .constructor-app {
    padding:
      10px 5px 22px;
  }

  .constructor-heading h1 {
    font-size: 25px;
  }

  .mode-selector {
    flex-direction: column;
  }

  .manual-source-grid {
    grid-template-columns: 1fr;
  }

  .manual-term-entry {
    grid-template-columns: 1fr;
  }

  .stage-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .stage-button {
    width: 100%;
  }
}

