          return (
            target &&
            validIds.indexOf(
              String(
                target.id
              )
            ) !== -1
          );
        }
      );
  }


  function hasValidSources() {
    return (
      getValidSelectedTargetIds()
        .length > 0 ||
      useWeb
    );
  }


  function hasValidPreview() {
    return (
      hasValidManualRules() &&
      buildFormula() !== '' &&
      hasValidSources()
    );
  }


  function getQueryName() {
    return String(
      getModel()
        .query_name ||
      ''
    ).trim();
  }


  function getQueryStatus() {
    var status =
      String(
        getModel()
          .query_status ||
        'active'
      )
        .trim()
        .toLowerCase();

    return (
      status === 'inactive'
        ? 'inactive'
        : 'active'
    );
  }


  function getAiInstruction() {
    return String(
      getModel()
        .ai_instruction ||
      ''
    ).trim();
  }


  function getAiExplanation() {
    return String(
      getModel()
        .ai_explanation ||
      ''
    ).trim();
  }


  function hasValidSaveForm() {
    return (
      getQueryName() !== '' &&
      hasValidPreview()
    );
  }


  async function syncQueryPayload() {
    var groupsJson =
      JSON.stringify(
        groups
      );

    var formula =
      buildFormula();

    lastGroupsValue =
      groupsJson;

    try {
      await appsmith.updateModel({
        query_groups_json:
          groupsJson,

        query_formula:
          formula
      });
    } catch (error) {
      console.error(
        'No fue posible sincronizar las reglas:',
        error
      );
    }
  }


  async function syncSourcePayload() {
    var idsJson =
      JSON.stringify(
        selectedTargetIds
      );

    lastTargetIdsValue =
      idsJson;

    lastUseWebValue =
      String(
        useWeb
      );

    try {
      await appsmith.updateModel({
        query_target_ids_json:
          idsJson,

        query_use_web:
          useWeb
      });
    } catch (error) {
      console.error(
        'No fue posible sincronizar las fuentes:',
        error
      );
    }
  }


