  function renderLibrary() {
    var queries =
      getQueries();

    var countElement =
      document.getElementById(
        'savedQueriesCount'
      );

    var listElement =
      document.getElementById(
        'savedQueriesList'
      );

    var paginationElement =
      document.getElementById(
        'savedQueriesPagination'
      );

    if (
      !countElement ||
      !listElement ||
      !paginationElement
    ) {
      return;
    }

    countElement.textContent =
      String(
        queries.length
      );

    clampPage();

    if (
      queries.length === 0
    ) {
      listElement.innerHTML =
        '<div class="library-empty">' +

          '<div class="empty-pulse"></div>' +

          '<strong>' +
            'Sin consultas guardadas' +
          '</strong>' +

          '<span>' +
            'Las consultas creadas aparecerán aquí.' +
          '</span>' +

        '</div>';

      paginationElement.innerHTML =
        '<button type="button" disabled>' +
          '←' +
        '</button>' +

        '<span>' +
          'Página 1 de 1' +
        '</span>' +

        '<button type="button" disabled>' +
          '→' +
        '</button>';

      return;
    }

    var pageSize =
      getPageSize();

    var startIndex =
      (
        currentPage -
        1
      ) *
      pageSize;

    var visibleQueries =
      queries.slice(
        startIndex,
        startIndex +
          pageSize
      );

    listElement.innerHTML =
      visibleQueries
        .map(
          renderQueryCard
        )
        .join('');

    var totalPages =
      getTotalPages();

    paginationElement.innerHTML =
      '<button' +
        ' type="button"' +
        ' data-action="prev-page"' +
        (
          currentPage <= 1
            ? ' disabled'
            : ''
        ) +
      '>' +
        '←' +
      '</button>' +

      '<span>' +
        'Página ' +
        escapeHtml(
          currentPage
        ) +
        ' de ' +
        escapeHtml(
          totalPages
        ) +
      '</span>' +

      '<button' +
        ' type="button"' +
        ' data-action="next-page"' +
        (
          currentPage >=
          totalPages
            ? ' disabled'
            : ''
        ) +
      '>' +
        '→' +
      '</button>';
  }


