  function renderModeSelector(
    mode
  ) {
    var selector =
      document.getElementById(
        'constructorModeSelector'
      );

    if (!selector) {
      return;
    }

    if (
      mode === 'home'
    ) {
      selector.classList.remove(
        'visible'
      );

      return;
    }

    selector.classList.add(
      'visible'
    );

    var buttons =
      selector.querySelectorAll(
        '[data-mode]'
      );

    buttons.forEach(
      function (button) {
        var buttonMode =
          button.getAttribute(
            'data-mode'
          );

        button.classList.toggle(
          'active',
          buttonMode === mode
        );
      }
    );
  }


  function setWizardLabels(
    mode
  ) {
    var step1Title =
      document.getElementById(
        'wizardStep1Title'
      );

    var step1Subtitle =
      document.getElementById(
        'wizardStep1Subtitle'
      );

    var step2Title =
      document.getElementById(
        'wizardStep2Title'
      );

    var step2Subtitle =
      document.getElementById(
        'wizardStep2Subtitle'
      );

    if (
      !step1Title ||
      !step1Subtitle ||
      !step2Title ||
      !step2Subtitle
    ) {
      return;
    }

    if (
      mode === 'ai'
    ) {
      step1Title.textContent =
        'Describir';

      step1Subtitle.textContent =
        'Explica qué monitorear';

      step2Title.textContent =
        'Revisar propuesta';

      step2Subtitle.textContent =
        'Ajusta la propuesta';

      return;
    }

    step1Title.textContent =
      'Construir';

    step1Subtitle.textContent =
      'Define las reglas';

    step2Title.textContent =
      'Fuentes';

    step2Subtitle.textContent =
      'Selecciona dónde escuchar';
  }


  function renderStepper(
    mode,
    step
  ) {
    var wizard =
      document.getElementById(
        'constructorWizard'
      );

    if (!wizard) {
      return;
    }

    if (
      mode === 'home'
    ) {
      wizard.hidden = true;

      return;
    }

    wizard.hidden = false;

    setWizardLabels(
      mode
    );

    var steps =
      wizard.querySelectorAll(
        '.wizard-step'
      );

    steps.forEach(
      function (stepElement) {
        var stepNumber =
          parseInt(
            stepElement.getAttribute(
              'data-step'
            ),
            10
          );

        stepElement.classList.toggle(
          'active',
          stepNumber === step
        );

        stepElement.classList.toggle(
          'completed',
          stepNumber < step
        );

        var numberElement =
          stepElement.querySelector(
            '.wizard-number'
          );

        if (numberElement) {
          numberElement.textContent =
            stepNumber < step
              ? '✓'
              : String(
                  stepNumber
                );
        }
      }
    );

    var lines =
      wizard.querySelectorAll(
        '.wizard-line'
      );

    lines.forEach(
      function (
        line,
        index
      ) {
        line.classList.toggle(
          'completed',
          index + 1 < step
        );
      }
    );
  }


  function getOperatorTerms(
    group,
    operator
  ) {
    if (!group) {
      return [];
    }

    if (
      operator === 'include'
    ) {
      return group.include;
    }

    if (
      operator === 'and'
    ) {
      return group.and;
    }

    if (
      operator === 'and_not'
    ) {
      return group.and_not;
    }

    return [];
  }


  function getOperatorChipClass(
    operator
  ) {
    if (
      operator === 'and'
    ) {
      return 'and';
    }

    if (
      operator === 'and_not'
    ) {
      return 'exclude';
    }

    return '';
  }


  function getEmptyTermsText(
    operator
  ) {
    if (
      operator === 'include'
    ) {
      return 'Agrega al menos un término para este grupo.';
    }

    if (
      operator === 'and'
    ) {
      return 'Sin condiciones obligatorias.';
    }

    return 'Sin exclusiones.';
  }


  function renderTerms(
    group,
    operator
  ) {
    var terms =
      getOperatorTerms(
        group,
        operator
      );

    if (
      terms.length === 0
    ) {
      return (
        '<span class="manual-empty-terms">' +
          escapeHtml(
            getEmptyTermsText(
              operator
            )
          ) +
        '</span>'
      );
    }

    var chipClass =
      getOperatorChipClass(
        operator
      );

    return terms
      .map(
        function (
          term,
          index
        ) {
          return (
            '<span class="manual-chip' +
              (
                chipClass
                  ? ' ' +
                    chipClass
                  : ''
              ) +
            '">' +

              '<span>' +
                escapeHtml(
                  term
                ) +
              '</span>' +

              '<button' +
                ' type="button"' +
                ' class="manual-chip-remove"' +
                ' data-remove-term="' +
                  escapeHtml(
                    operator
                  ) +
                '"' +
                ' data-group-no="' +
                  escapeHtml(
                    group.group_no
                  ) +
                '"' +
                ' data-term-index="' +
                  escapeHtml(
                    index
                  ) +
                '"' +
                ' aria-label="Eliminar término"' +
              '>' +
                '×' +
              '</button>' +

            '</span>'
          );
        }
      )
      .join('');
  }


  function renderRuleRow(
    group,
    operator
  ) {
    var badge = '';
    var badgeClass = '';
    var title = '';
    var description = '';
    var placeholder = '';

    if (
      operator === 'include'
