    if (
      operator === 'and'
    ) {
      badge =
        'AND';

      badgeClass =
        'and';

      title =
        'También debe contener';

      description =
        'Condiciones que deben cumplirse simultáneamente.';

      placeholder =
        'Añadir condición obligatoria';
    }

    if (
      operator === 'and_not'
    ) {
      badge =
        'AND NOT';

      badgeClass =
        'exclude';

      title =
        'Excluir';

      description =
        'Descarta resultados que contengan estos términos.';

      placeholder =
        'Añadir término a excluir';
    }

    return (
      '<div class="manual-rule-row">' +

        '<div class="manual-rule-copy">' +

