          '<strong>' +
            escapeHtml(
              title
            ) +
          '</strong>' +

          '<p>' +
            escapeHtml(
              description
            ) +
          '</p>' +

        '</div>' +

        '<div class="manual-rule-editor">' +

          '<div class="manual-term-entry">' +

            '<input' +
              ' type="text"' +
              ' class="manual-term-input"' +
              ' data-term-input="' +
                escapeHtml(
                  operator
                ) +
              '"' +
              ' data-group-no="' +
                escapeHtml(
                  group.group_no
                ) +
              '"' +
              ' maxlength="500"' +
              ' placeholder="' +
                escapeHtml(
                  placeholder
                ) +
              '"' +
              ' autocomplete="off"' +
            '>' +

            '<button' +
              ' type="button"' +
              ' class="manual-add-term"' +
              ' data-add-term="' +
                escapeHtml(
                  operator
                ) +
              '"' +
