  function formatPlatformLabel(value) {
    var text =
      String(
        value || ''
      )
        .trim()
        .replace(
          /[_-]+/g,
          ' '
        );

    if (!text) {
      return 'Red social';
    }

    return (
      text
        .charAt(0)
        .toUpperCase() +
      text.slice(1)
    );
  }


