  function normalizeAiProposal(
    proposal
  ) {
    var normalizedGroups =
      Array.isArray(
        proposal &&
        proposal.groups
      )
        ? proposal.groups
            .slice(
              0,
              getMaxGroups()
            )
            .map(
              normalizeGroup
            )
            .filter(
              function (group) {
                return (
                  group.include.length > 0
                );
              }
            )
        : [];

    var availableIds =
      getSelectableTargets()
        .map(
          function (target) {
            return String(
              target.id
            );
          }
        );

    var normalizedTargetIds =
      Array.isArray(
        proposal &&
        proposal.target_ids
      )
        ? proposal.target_ids
            .map(
              function (id) {
                return String(id);
              }
            )
            .filter(
              function (
                id,
                index,
                list
              ) {
                return (
                  availableIds.indexOf(id) !== -1 &&
                  list.indexOf(id) === index
                );
              }
            )
        : [];

    return {
      groups:
        normalizedGroups,

      target_ids:
        normalizedTargetIds,

      use_web:
        proposal &&
        proposal.use_web === true,

      explanation:
        String(
          proposal &&
          proposal.explanation ||
          ''
        )
          .trim()
          .slice(
            0,
            1000
          )
    };
  }


  async function applyAiResponse(
    response
  ) {
    aiRequestPending = false;
    aiGenerateArmed = false;
    aiGenerateInstruction = '';

    aiWarnings =
      Array.isArray(
        response.warnings
      )
        ? response.warnings
            .map(
              function (warning) {
                return String(
                  warning ||
                  ''
                ).trim();
              }
            )
            .filter(Boolean)
        : [];

    if (
      response.needs_clarification === true
    ) {
      aiWarnings = [];
    }

    if (
      response.ok !== true
    ) {
      aiFeedbackMessage =
        String(
          response.clarification_question ||
          'No fue posible construir una propuesta válida. Describe con mayor precisión qué deseas monitorear.'
        ).trim();

      await appsmith.updateModel({
        ai_generated:
          false,

        ai_proposal_json:
          '{}',

        ai_explanation:
          ''
      });

      renderCurrentView();
      return;
    }

    var proposal =
      normalizeAiProposal(
        response.proposal ||
        {}
      );

    groups =
      proposal.groups.length > 0
        ? proposal.groups
        : [
            createEmptyGroup(1)
          ];

    selectedTargetIds =
      proposal.target_ids;

    useWeb =
      proposal.use_web;

    if (
      !hasValidPreview()
    ) {
      aiFeedbackMessage =
        'La propuesta recibida no contiene una configuración válida para continuar.';

      await appsmith.updateModel({
        ai_generated:
          false,

        ai_proposal_json:
          JSON.stringify(
            proposal
          ),

        ai_explanation:
          proposal.explanation
      });

      renderCurrentView();
      return;
    }

    aiFeedbackMessage = '';

    var groupsJson =
      JSON.stringify(
        groups
      );

    var idsJson =
      JSON.stringify(
        selectedTargetIds
      );

    lastGroupsValue =
      groupsJson;

    lastTargetIdsValue =
      idsJson;

    lastUseWebValue =
      String(
        useWeb
      );

    currentStep = 2;

    await appsmith.updateModel({
      constructor_step:
        2,

      query_formula:
        buildFormula(),

      query_groups_json:
        groupsJson,

      query_target_ids_json:
        idsJson,

      query_use_web:
        useWeb,

      ai_proposal_json:
        JSON.stringify(
          proposal
        ),

      ai_explanation:
        proposal.explanation,

      ai_generated:
        true
    });

    lastStepValue =
      '2';

    renderCurrentView();
  }


  function renderCurrentView() {
    var mode =
      getMode();

    var step =
      getStep();

    var home =
      document.getElementById(
        'constructorHome'
      );

    hideAllViews();

    renderModeSelector(
      mode
    );

    renderStepper(
      mode,
      step
    );

    if (
      mode === 'home' ||
      step === 0
    ) {
      if (home) {
        home.hidden = false;
      }

      return;
    }

    var view =
      getViewElement(
        mode,
        step
      );

    if (!view) {
      return;
    }

    view.hidden = false;

    if (
      mode === 'manual'
    ) {
      if (
        step === 1
      ) {
        renderManualStep1(
          view
        );

        return;
      }

      if (
        step === 2
      ) {
        renderManualStep2(
          view
        );

        return;
      }

      if (
        step === 3
      ) {
        renderManualStep3(
          view
        );

        return;
      }

      if (
        step === 4
      ) {
        renderManualStep4(
          view
        );

        return;
      }
    }

    if (
      mode === 'ai'
    ) {
      if (
        step === 1
      ) {
        renderAiStep1(
          view
        );

        return;
      }

      if (
        step === 2
      ) {
        renderAiStep2(
          view
        );

        return;
      }

      if (
        step === 3
      ) {
        renderAiStep3(
          view
        );

        return;
      }

      if (
        step === 4
      ) {
        renderAiStep4(
          view
        );

        return;
      }
    }
  }


  function findGroup(
    groupNo
  ) {
    var number =
      parseInt(
        groupNo,
        10
      );

    for (
      var i = 0;
      i < groups.length;
      i += 1
    ) {
      if (
        groups[i].group_no ===
        number
      ) {
        return groups[i];
      }
    }

    return null;
  }


  function termExists(
    terms,
    candidate
  ) {
    var normalized =
      candidate
        .trim()
        .toLowerCase();

    return terms.some(
      function (term) {
        return (
          term
            .trim()
            .toLowerCase() ===
          normalized
        );
      }
    );
  }


  async function addTerm(
    button
  ) {
    var operator =
      button.getAttribute(
        'data-add-term'
      );

    var groupNo =
      parseInt(
        button.getAttribute(
          'data-group-no'
        ),
        10
      );

    var group =
      findGroup(
        groupNo
      );

    if (!group) {
      return;
    }

    var input =
      document.querySelector(
        '.manual-term-input' +
        '[data-group-no="' +
        String(groupNo) +
        '"]' +
        '[data-term-input="' +
        operator +
        '"]'
      );

    if (!input) {
      return;
    }

    var term =
      String(
        input.value || ''
      ).trim();

    if (
      !term ||
      term.length > 500
    ) {
      input.focus();
      return;
    }

    var terms =
      getOperatorTerms(
        group,
        operator
      );

    if (
      termExists(
        terms,
        term
      )
    ) {
      input.value = '';
      input.focus();
      return;
    }

    terms.push(
      term
    );

    input.value = '';

    await syncQueryPayload();

    renderCurrentView();
  }


  async function removeTerm(
    button
  ) {
    var operator =
      button.getAttribute(
        'data-remove-term'
      );

    var groupNo =
      parseInt(
        button.getAttribute(
          'data-group-no'
        ),
        10
      );

    var termIndex =
      parseInt(
        button.getAttribute(
          'data-term-index'
        ),
        10
      );

    var group =
      findGroup(
        groupNo
      );

    if (
      !group ||
      isNaN(termIndex)
    ) {
      return;
    }

    var terms =
      getOperatorTerms(
        group,
        operator
      );

    if (
      termIndex < 0 ||
      termIndex >= terms.length
    ) {
      return;
    }

    terms.splice(
      termIndex,
      1
    );

    await syncQueryPayload();

    renderCurrentView();
  }


  async function addGroup() {
    var maxGroups =
      getMaxGroups();

    if (
      groups.length >=
      maxGroups
    ) {
      return;
    }

    groups.push(
      createEmptyGroup(
        groups.length + 1
      )
    );

    await syncQueryPayload();

    renderCurrentView();
  }


  async function toggleTarget(
    targetId
  ) {
    var id =
      String(
        targetId || ''
      );

    if (!id) {
      return;
    }

    var target =
      getTargets()
        .find(
          function (item) {
            return (
              String(
                item.id
              ) === id
            );
          }
        );

    if (
      !target ||
      target.status !== 'active'
    ) {
      return;
    }

    var index =
      selectedTargetIds
        .indexOf(id);

    if (
      index === -1
    ) {
      selectedTargetIds.push(
        id
      );
    } else {
      selectedTargetIds.splice(
        index,
        1
      );
    }

    await syncSourcePayload();

    renderCurrentView();
  }


  async function toggleWeb() {
    useWeb =
      !useWeb;

    await syncSourcePayload();

    renderCurrentView();
  }


  async function generateAiProposal() {
    if (aiRequestPending) {
      return;
    }

    var input =
      document.getElementById(
        'aiInstructionInput'
      );

    var instruction =
      input
        ? String(
            input.value ||
            ''
          ).trim()
        : getAiInstruction();

    if (
      instruction.length < 20 ||
      instruction.length > 1500
    ) {
      aiFeedbackMessage =
        'Describe con al menos 20 caracteres qué deseas monitorear.';

      renderCurrentView();
      return;
    }

    aiRequestPending = true;
    aiFeedbackMessage = '';
    aiWarnings = [];

    aiGenerateArmed = true;
    aiGenerateInstruction = instruction;

    lastAiResponseValue =
      String(
        getModel()
          .ai_response ||
        ''
      );

    await appsmith.updateModel({
      ai_instruction:
        instruction,

      ai_generated:
        false,

      ai_proposal_json:
        '{}',

      ai_explanation:
        ''
    });

    renderCurrentView();
  }


  async function setMode(
    mode
  ) {
    if (
      mode !== 'manual' &&
      mode !== 'ai'
    ) {
      mode = 'home';
    }

    var step =
      mode === 'home'
        ? 0
        : 1;

    currentMode = mode;
    currentStep = step;

    await appsmith.updateModel({
      constructor_mode:
        mode,

      constructor_step:
        step
    });

    renderCurrentView();
  }


  async function setStep(
    step
  ) {
    var value =
      parseInt(
        step,
        10
      );

    if (
      isNaN(value) ||
      value < 1 ||
      value > 4
    ) {
      return;
    }

    currentStep = value;

    await appsmith.updateModel({
      constructor_step:
        value
    });

    renderCurrentView();
  }


  function updateSaveSummary(
    name
  ) {
    var normalizedName =
      String(
        name || ''
      ).trim();

    var valid =
      normalizedName !== '' &&
      hasValidPreview();

    var summaryIcon =
      document.getElementById(
        'manualSaveSummaryIcon'
      );

    var summaryText =
      document.getElementById(
        'manualSaveSummaryText'
      );

    var summaryState =
      document.getElementById(
        'manualSaveSummaryState'
      );

    var saveButton =
      document.getElementById(
        'manualSaveQueryButton'
      );

    if (summaryIcon) {
      summaryIcon.textContent =
        valid
          ? '✓'
          : '!';
    }

    if (summaryText) {
      summaryText.textContent =
        (
          normalizedName
            ? 'Nombre definido'
            : 'Falta asignar un nombre'
        ) +
        ' · Web: ' +
        (
          useWeb
            ? 'Sí'
            : 'No'
        );
    }

    if (summaryState) {
      summaryState.textContent =
        valid
          ? 'Lista para guardarse'
          : 'Completa los datos requeridos';
    }

    if (saveButton) {
      saveButton.disabled =
        !valid;
    }
  }


  async function syncSaveForm() {
    var nameInput =
      document.getElementById(
        'manualQueryName'
      );

    var statusInput =
      document.getElementById(
        'manualQueryStatus'
      );

    var name =
      nameInput
        ? String(
            nameInput.value || ''
          ).trim()
        : getQueryName();

    var status =
      statusInput
        ? String(
            statusInput.value ||
            'active'
          )
        : getQueryStatus();

    await appsmith.updateModel({
      query_name:
        name,

      query_status:
        status
    });

    updateSaveSummary(
      name
    );
  }


  async function saveManualQuery() {
    var nameInput =
      document.getElementById(
        'manualQueryName'
      );

    var statusInput =
      document.getElementById(
        'manualQueryStatus'
      );

    var name =
      nameInput
        ? String(
            nameInput.value || ''
          ).trim()
        : '';

    var status =
      statusInput
        ? String(
            statusInput.value ||
            'active'
          )
        : 'active';

    if (
      name === '' ||
      !hasValidPreview()
    ) {
      return;
    }

    await appsmith.updateModel({
      query_name:
        name,

      query_status:
        status,

      query_formula:
        buildFormula(),

      query_groups_json:
        JSON.stringify(
          groups
        ),

      query_target_ids_json:
        JSON.stringify(
          selectedTargetIds
        ),

      query_use_web:
        useWeb
    });

    appsmith.triggerEvent(
      'onSaveQuery'
    );
  }


  async function resetConstructor() {
    currentMode = 'home';
    currentStep = 0;

    aiRequestPending = false;
    aiGenerateArmed = false;
    aiGenerateInstruction = '';
    aiFeedbackMessage = '';
    aiWarnings = [];

    groups = [
      createEmptyGroup(1)
    ];

    selectedTargetIds = [];
    useWeb = false;

    var groupsJson =
      JSON.stringify(
        groups
      );

    var idsJson =
      JSON.stringify(
        selectedTargetIds
      );

    lastGroupsValue =
      groupsJson;

    lastTargetIdsValue =
      idsJson;

    lastUseWebValue =
      'false';

    await appsmith.updateModel({
      constructor_mode:
        'home',

      constructor_step:
        0,

      query_name:
        '',

      query_status:
        'active',

      query_formula:
        '',

      query_use_web:
        false,

      query_groups_json:
        groupsJson,

      query_target_ids_json:
        idsJson,

      ai_instruction:
        '',

      ai_proposal_json:
        '{}',

      ai_explanation:
        '',

      ai_generated:
        false
    });

    renderCurrentView();
  }


  document.addEventListener(
    'input',
    function (event) {

      if (
        event.target &&
        event.target.id ===
          'manualQueryName'
      ) {
        syncSaveForm();
      }

      if (
        event.target &&
        event.target.id ===
          'aiInstructionInput'
      ) {
        var aiButton =
          document.getElementById(
            'aiGenerateButton'
          );

        var aiText =
          String(
            event.target.value ||
            ''
          ).trim();

        if (aiButton) {
          aiButton.disabled =
            aiRequestPending ||
            aiText.length < 20 ||
            aiText.length > 1500;
        }
      }

    }
  );


  document.addEventListener(
    'change',
    function (event) {

      if (
        event.target &&
        event.target.id ===
          'manualQueryStatus'
      ) {
        syncSaveForm();
      }

    }
  );


  document.addEventListener(
    'keydown',
    function (event) {
      if (
        event.key !== 'Enter'
      ) {
        return;
      }

      var input =
        event.target.closest(
          '.manual-term-input[data-term-input]'
        );

      if (!input) {
        return;
      }

      event.preventDefault();

      var groupNo =
        input.getAttribute(
          'data-group-no'
        );

      var operator =
        input.getAttribute(
          'data-term-input'
        );

      var button =
        document.querySelector(
          '.manual-add-term' +
          '[data-group-no="' +
          groupNo +
          '"]' +
          '[data-add-term="' +
          operator +
          '"]'
        );

      if (button) {
        addTerm(
          button
        );
      }
    }
  );


  document.addEventListener(
    'click',
    function (event) {

      var generateAiButton =
        event.target.closest(
          '[data-generate-ai]'
        );

      if (generateAiButton) {
        generateAiProposal();

        return;
      }


      var saveButton =
        event.target.closest(
          '[data-save-query]'
        );

      if (saveButton) {
        saveManualQuery();

        return;
      }


      var sourceTarget =
        event.target.closest(
          '[data-source-target-id]'
        );

      if (sourceTarget) {
        toggleTarget(
          sourceTarget.getAttribute(
            'data-source-target-id'
          )
        );

        return;
      }


      var webSource =
        event.target.closest(
          '[data-toggle-web]'
        );

      if (webSource) {
        toggleWeb();

        return;
      }


      var addTermButton =
        event.target.closest(
          '[data-add-term]'
        );

      if (addTermButton) {
        addTerm(
          addTermButton
        );

        return;
      }


      var removeTermButton =
        event.target.closest(
          '[data-remove-term]'
        );

      if (removeTermButton) {
        removeTerm(
          removeTermButton
        );

        return;
      }


      var addGroupButton =
        event.target.closest(
          '[data-add-group]'
        );

      if (addGroupButton) {
        addGroup();

        return;
      }


      var nextStepButton =
        event.target.closest(
          '[data-next-step]'
        );

      if (nextStepButton) {
        setStep(
          nextStepButton.getAttribute(
            'data-next-step'
          )
        );

        return;
      }


      var prevStepButton =
        event.target.closest(
          '[data-prev-step]'
        );

      if (prevStepButton) {
        setStep(
          prevStepButton.getAttribute(
            'data-prev-step'
          )
        );

        return;
      }


      var homeButton =
        event.target.closest(
          '[data-nav-home]'
        );

      if (homeButton) {
        resetConstructor();

        return;
      }


      var startModeButton =
        event.target.closest(
          '[data-start-mode]'
        );

      if (startModeButton) {
        setMode(
          startModeButton.getAttribute(
            'data-start-mode'
          )
        );

        return;
      }


      var modeButton =
        event.target.closest(
          '[data-mode]'
        );

      if (modeButton) {
        setMode(
          modeButton.getAttribute(
            'data-mode'
          )
        );

        return;
      }


      var newQueryButton =
        event.target.closest(
          '#newQueryButton'
        );

      if (newQueryButton) {
        resetConstructor();

        return;
      }


      var paginationButton =
        event.target.closest(
          '[data-action]'
        );

      if (!paginationButton) {
        return;
      }

      var action =
        paginationButton.getAttribute(
          'data-action'
        );

      if (
        action ===
        'prev-page'
      ) {
        if (
          currentPage >
          1
        ) {
          currentPage -= 1;

          renderLibrary();
        }

        return;
      }

      if (
        action ===
        'next-page'
      ) {
        var totalPages =
          getTotalPages();

        if (
          currentPage <
          totalPages
        ) {
          currentPage += 1;

          renderLibrary();
        }
      }
    }
  );


  var initialMode =
    String(
      getModel().constructor_mode ||
      'home'
    )
      .trim()
      .toLowerCase();

  currentMode =
    initialMode === 'manual' ||
    initialMode === 'ai'
      ? initialMode
      : 'home';

  var initialStep =
    parseInt(
      getModel().constructor_step ||
      0,
      10
    );

  currentStep =
    !isNaN(initialStep) &&
    initialStep >= 0 &&
    initialStep <= 4
      ? initialStep
      : 0;

  loadGroupsFromModel();
  loadSourcesFromModel();

  renderLibrary();
  renderCurrentView();


  lastQueriesValue =
    String(
      getModel().queries || ''
    );

  lastTargetsValue =
    String(
      getModel().targets || ''
    );

  lastModeValue =
    String(
      getModel()
        .constructor_mode ||
      'home'
    );

  lastStepValue =
    String(
      getModel()
        .constructor_step ||
      0
    );

  lastGroupsValue =
    String(
      getModel()
        .query_groups_json ||
      '[]'
    );

  lastTargetIdsValue =
    String(
      getModel()
        .query_target_ids_json ||
      '[]'
    );

  lastUseWebValue =
    String(
      getModel()
        .query_use_web ||
      false
    );

  lastAiResponseValue =
    String(
      getModel()
        .ai_response ||
      ''
    );


  if (
    typeof appsmith.onModelChange ===
    'function'
  ) {
    appsmith.onModelChange(
      function (newModel) {

        var model =
          newModel ||
          getModel();

        var queriesValue =
          String(
            model.queries || ''
          );

        var targetsValue =
          String(
            model.targets || ''
          );

        var modeValue =
          String(
            model.constructor_mode ||
            'home'
          );

        var stepValue =
          String(
            model.constructor_step ||
            0
          );

        var groupsValue =
          String(
            model.query_groups_json ||
            '[]'
          );

        var targetIdsValue =
          String(
            model.query_target_ids_json ||
            '[]'
          );

        var useWebValue =
          String(
            model.query_use_web ||
            false
          );

        var aiResponseValue =
          String(
            model.ai_response ||
            ''
          );

        var aiInstructionValue =
          String(
            model.ai_instruction ||
            ''
          ).trim();


        if (
          aiGenerateArmed &&
          aiRequestPending &&
          getMode() === 'ai' &&
          aiInstructionValue ===
            aiGenerateInstruction
        ) {
          aiGenerateArmed = false;

          appsmith.triggerEvent(
            'onGenerateAI'
          );
        }


        if (
          queriesValue !==
          lastQueriesValue
        ) {
          lastQueriesValue =
            queriesValue;

          currentPage = 1;

          renderLibrary();
        }


        if (
          targetsValue !==
          lastTargetsValue
        ) {
          lastTargetsValue =
            targetsValue;

          if (
            modeValue === 'manual' &&
            (
              stepValue === '2' ||
              stepValue === '3' ||
              stepValue === '4'
            )
          ) {
            renderCurrentView();
          }
        }


        if (
          groupsValue !==
          lastGroupsValue
        ) {
          lastGroupsValue =
            groupsValue;

          loadGroupsFromModel();

          if (
            modeValue === 'manual' &&
            (
              stepValue === '1' ||
              stepValue === '3' ||
              stepValue === '4'
            )
          ) {
            renderCurrentView();
          }
        }


        if (
          targetIdsValue !==
            lastTargetIdsValue ||
          useWebValue !==
            lastUseWebValue
        ) {
          lastTargetIdsValue =
            targetIdsValue;

          lastUseWebValue =
            useWebValue;

          loadSourcesFromModel();

          if (
            modeValue === 'manual' &&
            (
              stepValue === '2' ||
              stepValue === '3' ||
              stepValue === '4'
            )
          ) {
            renderCurrentView();
          }
        }


        if (
          aiResponseValue !==
          lastAiResponseValue
        ) {
          lastAiResponseValue =
            aiResponseValue;

          if (
            getMode() === 'ai'
          ) {
            var aiResponse =
              asObject(
                model.ai_response
              );

            if (
              Object.keys(
                aiResponse
              ).length > 0 &&
              (
                aiResponse.ok === true ||
                aiResponse.needs_clarification === true
              )
            ) {
              applyAiResponse(
                aiResponse
              );
            }
          }
        }


        if (
          modeValue !==
            lastModeValue ||
          stepValue !==
            lastStepValue
        ) {
          lastModeValue =
            modeValue;

          lastStepValue =
            stepValue;

          renderCurrentView();
        }

      }
    );
  }

});
